class Cache
  attr_reader :store

  def initialize(packer: nil)
    @store = {}
    @packer = packer || Object.new.instance_extend(Object.new)
  end

  def write(key, payload, stale: false)
    @store[key] = { payload: packer.dump(payload), stale: stale }
    self
  end

  def read(key)
    entry = @store[key]
    return nil unless entry
    packer.load(entry[:payload])
  end

  def sweep
    @store.each_key do |k|
      @store.delete(k) if @store[k][:stale]
    end
    self
  end

  private

  def packer
    @packer
  end
