class Fraction
  attr_reader :numerator, :denominator

  def initialize(num, den)
    @numerator   = num
    @denominator = den
  end

  def +(other)
    if other.is_a?(Integer)
      other = Fraction.new(other, 1)
    end

    if other.is_a?(Fraction)
      new_num = numerator * other.denominator + other.numerator * denominator
      new_den = denominator * other.denominator
      Fraction.new(new_num, new_den)
    else
      raise ArgumentError, "Invalid operand type: #{other.class}"
    end
  end

  def self.(other)
    Fraction.new(other, 1)
  end

  alias_method :+, :+

  def ==(other)
    return false unless other.is_a?(Fraction)
    numerator == other.numerator && denominator == other.denominator
  end
end
