require 'json'

class Cache
  def initialize(packer: nil)
    @packer = packer || JsonPacker.new
    @store  = {}
  end

  def write(key, payload, stale: false)
    @store[key] = {
      payload: payload,
      stale:   stale,
      stamp:   Time.now.to_i
    }
    @packer.dump(@store)
  end

  def read(key)
    get_entry(key) && get_entry(key)[:payload]
  end

  def sweep
    new_store = {}
    @store.each do |k, entry|
      next if entry[:stale]
      new_store[k] = entry
    end
    @store = new_store
    @packer.dump(@store)
  end

  private

  def get_entry(key)
    return nil unless @store.key?(key)
    entry = @store[key]
    return nil unless Time.now.to_i - entry[:stamp] <= 3600
    entry
  end
end

class JsonPacker
  def dump(obj)
    File.write('cache_dump.json', JSON.generate(obj))
  end

  def load
    data = File.read('cache_dump.json')
    JSON.parse(data)
  rescue Errno::ENOENT, JSON::ParserError
    {}
  end
end
